using System.Text.Json;
using DocParse.Modules.Usage.Contracts;
using Npgsql;

namespace DocParse.Modules.Usage.Infrastructure;

public sealed record UsageWork(Guid Id,Guid OrganizationId,Guid? BotId,string Feature,string Channel,UsageBound[] Maximum,UsageBound[] Meters,bool Success,Guid Lease);
public sealed class UsageLedger(IConfiguration config)
{
 private static readonly JsonSerializerOptions Json=new(JsonSerializerDefaults.Web);
 private async Task<NpgsqlConnection> Open(CancellationToken ct){var db=new NpgsqlConnection(config["PostgreSQL:ConnectionString"]);await db.OpenAsync(ct);return db;}
 private static NpgsqlCommand Cmd(NpgsqlConnection db,string sql,params(string Name,object Value)[] args){var cmd=new NpgsqlCommand(sql,db);foreach(var(n,v)in args)cmd.Parameters.AddWithValue(n,v);return cmd;}
 public async Task<string> Plan(Guid org,CancellationToken ct){await using var db=await Open(ct);await using var cmd=Cmd(db,"SELECT next_plan_key FROM usage.organization_settings WHERE organization_id=@org",("org",org));return await cmd.ExecuteScalarAsync(ct)as string??"free";}
 public async Task SetPlan(Guid org,string plan,CancellationToken ct){await using var db=await Open(ct);await using var cmd=Cmd(db,"INSERT INTO usage.organization_settings(organization_id,next_plan_key) VALUES(@org,@plan) ON CONFLICT(organization_id) DO UPDATE SET next_plan_key=excluded.next_plan_key",("org",org),("plan",plan));await cmd.ExecuteNonQueryAsync(ct);}
 public async Task Create(Guid id,Guid org,Guid? bot,string feature,string channel,UsageBound[] maximum,CancellationToken ct){await using var db=await Open(ct);await using var cmd=Cmd(db,"INSERT INTO usage.operations(id,organization_id,bot_id,resource_id,feature,channel,state,maximum) VALUES(@id,@org,@bot,@bot,@feature,@channel,'reserving',@maximum::jsonb)",("id",id),("org",org),("bot",(object?)bot??DBNull.Value),("feature",feature),("channel",channel),("maximum",JsonSerializer.Serialize(maximum,Json)));if(bot is null)cmd.Parameters["bot"].NpgsqlDbType=NpgsqlTypes.NpgsqlDbType.Uuid;await cmd.ExecuteNonQueryAsync(ct);}
 public async Task Transition(Guid id,string state,string? error,CancellationToken ct){await using var db=await Open(ct);await using var cmd=Cmd(db,"UPDATE usage.operations SET state=@state,error_code=@error,updated_at=now() WHERE id=@id AND state IN('reserving','running')",("id",id),("state",state),("error",(object?)error??DBNull.Value));cmd.Parameters["error"].NpgsqlDbType=NpgsqlTypes.NpgsqlDbType.Text;await cmd.ExecuteNonQueryAsync(ct);}
 public async Task Record(Guid id,string provider,string model,long input,long output,CancellationToken ct){
  if(input<0||output<0)throw new InvalidDataException("Invalid metering response.");await using var db=await Open(ct);await using var tx=await db.BeginTransactionAsync(ct);
  UsageBound[] meters;await using(var get=Cmd(db,"SELECT meters::text FROM usage.operations WHERE id=@id AND state='running' FOR UPDATE",("id",id))){var raw=await get.ExecuteScalarAsync(ct)as string;if(raw is null)throw new UsageServiceUnavailable();meters=JsonSerializer.Deserialize<UsageBound[]>(raw,Json)??[];}
  var list=meters.ToList();var index=list.FindIndex(m=>m.Provider==provider&&m.Model==model);if(index<0)list.Add(new(provider,model,input,output));else list[index]=list[index]with{Input=checked(list[index].Input+input),Output=checked(list[index].Output+output)};
  await using var update=Cmd(db,"UPDATE usage.operations SET meters=@meters::jsonb,updated_at=now() WHERE id=@id",("id",id),("meters",JsonSerializer.Serialize(list,Json)));await update.ExecuteNonQueryAsync(ct);await tx.CommitAsync(ct);
 }
 public async Task Finish(Guid id,bool success,CancellationToken ct){await using var db=await Open(ct);await using var cmd=Cmd(db,"UPDATE usage.operations SET state='pending',success=@success,updated_at=now(),retry_at=now() WHERE id=@id AND state='running'",("id",id),("success",success));if(await cmd.ExecuteNonQueryAsync(ct)!=1)throw new UsageServiceUnavailable();}
 public async Task<UsageWork?> Claim(CancellationToken ct){await using var db=await Open(ct);var lease=Guid.NewGuid();await using var cmd=Cmd(db,"UPDATE usage.operations SET state='dispatching',lease_id=@lease,lease_until=now()+interval '60 seconds',attempts=attempts+1 WHERE id=(SELECT id FROM usage.operations WHERE (state='pending' AND retry_at<=now()) OR (state='dispatching' AND lease_until<now()) OR (state IN('reserving','running') AND updated_at<now()-interval '20 minutes') ORDER BY created_at FOR UPDATE SKIP LOCKED LIMIT 1) RETURNING id,organization_id,resource_id,feature,channel,maximum::text,meters::text,success",("lease",lease));await using var r=await cmd.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))return null;return new(r.GetGuid(0),r.GetGuid(1),r.IsDBNull(2)?null:r.GetGuid(2),r.GetString(3),r.GetString(4),JsonSerializer.Deserialize<UsageBound[]>(r.GetString(5),Json)??[],JsonSerializer.Deserialize<UsageBound[]>(r.GetString(6),Json)??[],r.GetBoolean(7),lease);}
 public async Task Resolve(UsageWork work,bool done,string? error,CancellationToken ct){await using var db=await Open(ct);await using var cmd=Cmd(db,"UPDATE usage.operations SET state=@state,error_code=@error,updated_at=now(),lease_id=NULL,lease_until=NULL,retry_at=now()+make_interval(secs=>LEAST(300,5*attempts)) WHERE id=@id AND lease_id=@lease AND state='dispatching'",("id",work.Id),("lease",work.Lease),("state",done?"complete":"pending"),("error",(object?)error??DBNull.Value));cmd.Parameters["error"].NpgsqlDbType=NpgsqlTypes.NpgsqlDbType.Text;await cmd.ExecuteNonQueryAsync(ct);}
 public async Task<object> LocalState(Guid org,CancellationToken ct){await using var db=await Open(ct);await using var cmd=Cmd(db,"SELECT count(*) FILTER(WHERE state NOT IN('complete','denied')),count(*) FILTER(WHERE error_code IS NOT NULL AND state NOT IN('complete','denied')) FROM usage.operations WHERE organization_id=@org",("org",org));await using var r=await cmd.ExecuteReaderAsync(ct);await r.ReadAsync(ct);return new{pendingOperations=r.GetInt64(0),failedSynchronizations=r.GetInt64(1)};}
}
